def determine_direction(dx, dy, threshold):
    ax = abs(dx)
    ay = abs(dy)
    if max(ax, ay) < threshold['px_min']:
        return None
    if ax >= ay * threshold['axis_ratio']:
        return 'right' if dx > 0 else 'left'
    if ay >= ax * threshold['axis_ratio']:
        return 'down' if dy > 0 else 'up'
    return None

